  email: 'user@example.com',
  options: {
    emailRedirectTo: 'https://example.com/welcome',
  },
});

if (error) console.error(error);

// v2: getUser() makes a request to the auth server for trusted user data
const { data: { user }, error } = await supabase.auth.getUser();

if (error) console.error(error);
if (user) {
  console.log(user.email);
  console.log(user.id);
}

// v2: getSession() is async
const { data: { session }, error } = await supabase.auth.getSession();

if (session) {
  console.log(session.access_token);
  console.log(session.user);
}

// v2: insert() does NOT return rows by default
// Chain .select() to get the inserted row back
const { data, error } = await supabase
  .from('posts')
  .insert({ title: 'Hello', body: 'World', user_id: userId })
  .select()
  .single();

if (error) throw error;
console.log(data.id); // the inserted row's id

// v2: update() does NOT return rows by default
const { data, error } = await supabase
  .from('profiles')
  .update({ bio: 'New bio', updated_at: new Date().toISOString() })
  .eq('id', userId)
  .select()
  .single();

if (error) throw error;
console.log(data); // the updated profile

// v2: Realtime uses channels
const channel = supabase
  .channel('users-changes')
  .on(
    'postgres_changes',
    { event: '*', schema: 'public', table: 'users' },
    (payload) => {
      console.log('Change received!', payload);
      if (payload.eventType === 'INSERT') console.log(payload.new);
      if (payload.eventType === 'UPDATE') console.log(payload.old, '->', payload.new);
    }
  )
  .subscribe();

// To unsubscribe:
