import { createClient } from '@supabase/supabase-js';
import { Database } from './database.types'; // generated with: supabase gen types typescript

const supabase = createClient<Database>(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
);

// Now queries are fully typed
const { data, error } = await supabase
  .from('users')  // only valid table names
  .select('id, name, email'); // only valid columns
// data is typed as Array<{ id: number, name: string, email: string }>

// v2: auth.update() renamed to auth.updateUser()
const { data: { user }, error } = await supabase.auth.updateUser({
  email: 'newemail@example.com',
  password: 'newpassword',
  data: {
    displayName: 'Alice',
    avatar_url: 'https://example.com/avatar.png',
  },
});

if (error) console.error(error);

import { createClient } from '@supabase/supabase-js';

// v2: options are nested under auth, db, global, and realtime
const supabase = createClient(url, key, {
  db: {
    schema: 'custom', // moved from top-level
  },
  auth: {
    persistSession: false, // moved from top-level
    autoRefreshToken: true,
    detectSessionInUrl: true,
  },
  global: {
    headers: { 'x-my-custom-header': 'my-app-name' },
  },
});

// v2: no more .api. namespace, method is directly on auth
const { data, error } = await supabase.auth.resetPasswordForEmail(
  'user@example.com',
  {
    redirectTo: 'https://example.com/update-password',
  }
);

if (error) console.error(error);

// getSession() reads from local storage - NOT safe for server-side trust
// getUser() always makes a request to the auth server to validate the JWT

// For server-side user verification (e.g., API route or SSR):
const { data: { user }, error } = await supabase.auth.getUser();

if (error || !user) {
  // Unauthorized
  return;
}

// user.id is now verified as authentic
console.log(user.id, user.email);

// v2: delete() does NOT return rows by default
// Chain .select() to get the deleted rows back
const { data, error } = await supabase
  .from('posts')
  .delete()
  .eq('id', postId)
  .select();

if (error) throw error;
// data contains the deleted row(s)
console.log('Deleted:', data);

// If you don't need the deleted rows, simpler:
const { error: deleteError } = await supabase
  .from('posts')
  .delete()
  .eq('id', postId);

// database.types.ts is generated with: supabase gen types typescript --project-id ...
import { Database, Tables, Enums } from './database.types';

// Shorthand for table row types
type Profile = Tables<'profiles'>;
type Post = Tables<'posts'>;

// For enums:
type UserRole = Enums<'user_role'>;

// Use in components:
function ProfileCard({ profile }: { profile: Profile }) {
  return <div>{profile.display_name}</div>;
}
